 draw("KML",75,759,47,serif,white);draw("KENDENUP MINI LOADERS",35,738,12,bold,white);draw("WET OR DRY HIRE",35,721,9,bold,white);
 draw("INVOICE",365,782,29,bold,white);draw(n,365,751,19,bold,white);
